from typing import Literal

from pydantic import BaseModel, Field


# =========================================
# 1. Communication Style
# =========================================

class CommunicationStyle(BaseModel):
    description: str

    characteristics: list[str]


# =========================================
# 2. Behavioural Characteristics
# =========================================

class BehaviouralCharacteristics(BaseModel):
    # Explicitly supplied by the trainee
    trainee_provided: list[str]

    # Generated by Character Creation Agent
    generated: list[str]


# =========================================
# 3. Attitude Towards Change
# =========================================

class AttitudeTowardsChange(BaseModel):
    readiness: str

    openness: str

    confidence: str

    description: str


# =========================================
# 4. Emotional Triggers
# =========================================

class EmotionalTrigger(BaseModel):
    trigger: str

    likely_response: str


# =========================================
# 5. Initial Emotional State
# =========================================

class InitialEmotionalState(BaseModel):
    """
    All values use a 0-10 scale.

    These represent the emotional state at the
    beginning of the patient simulation.
    """

    frustration: int = Field(ge=0, le=10)

    anxiety: int = Field(ge=0, le=10)

    trust: int = Field(ge=0, le=10)

    motivation: int = Field(ge=0, le=10)

    confidence: int = Field(ge=0, le=10)

    willingness_to_discuss: int = Field(ge=0, le=10)

    willingness_to_change: int = Field(ge=0, le=10)


# =========================================
# 6. Individual Patient Character
# =========================================

class PatientCharacter(BaseModel):

    character_id: str

    character_name: str

    character_type: str

    description: str

    personality_traits: list[str]

    emotional_tendencies: list[str]

    communication_style: CommunicationStyle

    behavioural_characteristics: BehaviouralCharacteristics

    attitude_towards_change: AttitudeTowardsChange

    emotional_triggers: list[EmotionalTrigger]

    initial_emotional_state: InitialEmotionalState

    initial_state_explanation: str


# =========================================
# 7. Complete Character Collection
# =========================================

class CharacterCollection(BaseModel):

    patient_id: str

    patient_name: str

    characters: list[PatientCharacter]

    status: Literal[
        "generating",
        "refining",
        "awaiting_confirmation",
        "confirmed"
    ]


# =========================================
# 8. Agent Response
# =========================================

class CharacterCreationTurn(BaseModel):

    assistant_message: str

    action: Literal[
        "present_characters",
        "ask_question",
        "confirm_collection"
    ]

    character_collection: CharacterCollection

    affected_character_ids: list[str]